// Purpose: ROW-120 (REQ-045, REQ-013, REQ-011) — on the checker page, in every browser of the
// harness, every way the text can change besides typing — cut, drag and drop, paste by the browser's
// paste command, keyboard composition, dictation and autocorrect, undo and redo — clears every
// highlight and the count like typing; and undo straight after a Replace restores exactly the text
// from before that Replace and clears every highlight and the count.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) with a fresh seed per run; expected texts are the test's own record.
//
// Test argument
// ROW-120 promise: cut, drag and drop, context-menu paste, keyboard autocorrect and composition,
//   dictation, and undo or redo clear every highlight and the count like typing; undo straight after
//   a Replace (Ctrl+Z, Cmd+Z or the Edit menu) restores exactly the text before that Replace and
//   clears every highlight and the count (A-049, A-053; REQ-045 fail-if: any other text, an empty box,
//   the paste undone, or a highlight or the old count left; REQ-013).
// ROW-120 wrong product: a page that clears the check on `keydown` only — cut by shortcut clears
//   but a drop, a paste, an IME commit or dictation (input events with no key) leave stale
//   highlights; or a Replace that assigns the box's value directly, so the browser's undo after it
//   undoes the original paste and empties the box.
// ROW-120 given: a text with two fresh misspellings, checked afresh before each path; when, in turn:
//   Ctrl/Cmd+X on a selected word (cut); a drag from another source dropped on the box (drag and
//   drop); Ctrl/Cmd+V (the paste command a context-menu Paste runs); an IME composition committed
//   (Chromium: the DevTools IME composition; WebKit and Firefox: a text insertion without key events,
//   which is how a composition or dictation commit reaches a page); a phrase inserted without key
//   events (dictation); a selected word replaced by an insertion without key events (autocorrect);
//   Ctrl/Cmd+Z (undo — the command the Edit menu's Undo runs) and Ctrl/Cmd+Shift+Z (redo); and,
//   after choosing a suggestion, Ctrl/Cmd+Z straight away; then: each path changed the text and
//   left no highlight and no count line; the undo after Replace gives exactly the text from before
//   the Replace — and before each path the highlights and the count were shown.
// ROW-120 controls: a check of the text shows the two highlights and the count — the state every
//   path must clear is reached; untouched by a path left uncleared.
// ROW-120 technique: one fresh check per path, before/after on the same page, every path's
//   assertions soft so one run reports every path; the engine door reaches the context menu, the Edit
//   menu and a phone keyboard's autocorrect only through the commands and input events they run —
//   the paste command, the undo command, an insertion without key events — which is what the page
//   receives from them (stated as this test's limit: the native menus themselves are not pressed).
// cases: ROW-120 target=ROW-120-every-non-typing-edit-clears-the-check-and-undo-after-replace-restores-the-text control=ROW-120-control-the-check-shows-highlights-and-the-count

import { expect, test, type Page } from '@playwright/test';
import { accentPopulation, asActor, compose, el, enterOffer, freshRandom, openChecker, pressCheck, readHighlights, ROLES, type Rng } from './harness';
import {
  chooseSuggestion,
  openMenuByPointer,
  putOnClipboard,
  readCount,
  readMenu,
  readOfferText,
  scratchPage,
  settle,
  sprinkle,
  typeAtEnd,
} from './suggestions-helpers';

const WAIT_MS = 15_000;
const soft = expect.configure({ soft: true });

function offer(rng: Rng) {
  const pop = accentPopulation();
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  return compose(sprinkle(rng, [a.stripped, b.stripped]));
}

/** Checks the box's current text and waits for at least two highlights and the count line. */
async function freshCheck(page: Page, label: string, seed: number): Promise<string> {
  const text = await readOfferText(page);
  expect((await pressCheck(page)).status, `ROW-120 (${label}): the check before the path is answered`).toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).length, { message: `ROW-120 (${label}): before the path the misspellings are highlighted (seed ${seed})`, timeout: WAIT_MS })
    .toBeGreaterThanOrEqual(2);
  await expect.poll(async () => (await readCount(page)).shown, { message: `ROW-120 (${label}): before the path the count line shows`, timeout: WAIT_MS }).toBe(true);
  return text;
}

/** After a path: the text changed, and no highlight and no count line remain (soft: every path reports). */
async function cleared(page: Page, before: string, label: string): Promise<string> {
  await settle(page);
  const now = await readOfferText(page);
  soft(now, `ROW-120 (${label}): the path changed the text (setup: the engine performed it)`).not.toBe(before);
  await soft
    .poll(async () => (await readHighlights(page, await readOfferText(page))).map((h) => h.word), { message: `ROW-120 (${label}): no highlight remains`, timeout: WAIT_MS })
    .toEqual([]);
  await soft.poll(async () => (await readCount(page)).shown, { message: `ROW-120 (${label}): the count line is gone`, timeout: WAIT_MS }).toBe(false);
  return now;
}

async function caretAtEnd(page: Page) {
  await page.bringToFront();
  await el(page, ROLES.offer).first().focus();
  await page.keyboard.press('ControlOrMeta+End');
}

async function selectLastWord(page: Page) {
  await caretAtEnd(page);
  await page.keyboard.press('ControlOrMeta+Shift+ArrowLeft');
}

test('ROW-120-every-non-typing-edit-clears-the-check-and-undo-after-replace-restores-the-text', async ({ page, context, browserName }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text } = offer(rng);
  const scratch = await scratchPage(context);
  await openChecker(page);
  await enterOffer(page, text);
  let t: string;

  // cut
  t = await freshCheck(page, 'cut', rng.seed);
  await selectLastWord(page);
  await page.keyboard.press('ControlOrMeta+X');
  await cleared(page, t, 'cut — Ctrl/Cmd+X');

  // drag and drop: a phrase dragged from another source onto the box
  t = await freshCheck(page, 'drag and drop', rng.seed);
  await page.evaluate(() => {
    const src = document.createElement('span');
    src.id = 'vid-drag-source';
    src.textContent = 'experiencia';
    src.draggable = true;
    src.style.cssText = 'position:fixed;left:0;top:0;z-index:2147483647;background:#fff;padding:4px';
    src.addEventListener('dragstart', (e) => e.dataTransfer?.setData('text/plain', ' experiencia '));
    document.body.appendChild(src);
  });
  await page.locator('#vid-drag-source').dragTo(el(page, ROLES.offer).first());
  await page.evaluate(() => document.getElementById('vid-drag-source')?.remove());
  await cleared(page, t, 'drag and drop');

  // paste: the browser's paste command (what a context-menu Paste runs)
  t = await freshCheck(page, 'paste', rng.seed);
  await putOnClipboard(scratch, ' oficina');
  await caretAtEnd(page);
  await page.keyboard.press('ControlOrMeta+V');
  await cleared(page, t, 'paste — the paste command');

  // keyboard composition, committed
  t = await freshCheck(page, 'composition', rng.seed);
  await caretAtEnd(page);
  if (browserName === 'chromium') {
    const cdp = await context.newCDPSession(page);
    await cdp.send('Input.imeSetComposition', { text: ' equi', selectionStart: 5, selectionEnd: 5 });
    await cdp.send('Input.insertText', { text: ' equipo' });
    await cdp.detach();
  } else {
    await page.keyboard.insertText(' equipo');
  }
  await cleared(page, t, 'keyboard composition');

  // dictation: a phrase arriving with no key events
  t = await freshCheck(page, 'dictation', rng.seed);
  await caretAtEnd(page);
  await page.keyboard.insertText(' con horario flexible');
  await cleared(page, t, 'dictation');

  // autocorrect: a selected word replaced with no key events
  t = await freshCheck(page, 'autocorrect', rng.seed);
  await selectLastWord(page);
  await page.keyboard.insertText('flexibles');
  await cleared(page, t, 'autocorrect');

  // undo and redo of a typed edit
  await typeAtEnd(page, ' y');
  t = await freshCheck(page, 'undo', rng.seed);
  await caretAtEnd(page);
  await page.keyboard.press('ControlOrMeta+Z');
  await cleared(page, t, 'undo — Ctrl/Cmd+Z');
  t = await freshCheck(page, 'redo', rng.seed);
  await caretAtEnd(page);
  await page.keyboard.press('ControlOrMeta+Shift+Z');
  await cleared(page, t, 'redo — Ctrl/Cmd+Shift+Z');

  // undo straight after a Replace
  t = await freshCheck(page, 'undo after Replace', rng.seed);
  const first = (await readHighlights(page, t))[0];
  await openMenuByPointer(page, t, first.start, 'ROW-120');
  const menu = await readMenu(page);
  expect(menu.suggestions.length, `ROW-120 (undo after Replace): "${first.word}"'s menu holds a suggestion — ${JSON.stringify(menu)}`).toBeGreaterThan(0);
  await chooseSuggestion(page, menu.suggestions[0], 'ROW-120');
  await expect.poll(() => readOfferText(page), { message: 'ROW-120 (undo after Replace): the Replace changed the text', timeout: WAIT_MS }).not.toBe(t);
  await page.keyboard.press('ControlOrMeta+Z');
  await expect
    .poll(() => readOfferText(page), { message: `ROW-120 (undo after Replace): Ctrl/Cmd+Z straight after the Replace restores exactly the text from before it (seed ${rng.seed})`, timeout: WAIT_MS })
    .toBe(t);
  await expect.poll(async () => (await readHighlights(page, t)).map((h) => h.word), { message: 'ROW-120 (undo after Replace): no highlight remains after the undo', timeout: WAIT_MS }).toEqual([]);
  await expect.poll(async () => (await readCount(page)).shown, { message: 'ROW-120 (undo after Replace): the count line is gone after the undo', timeout: WAIT_MS }).toBe(false);
});

test('ROW-120-control-the-check-shows-highlights-and-the-count', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text } = offer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  await freshCheck(page, 'control', rng.seed);
});
